/**
 * A filter for customers by name.
 *
 * @param nameFilter case-insensitive substring to match against first or last name;
 *                   if empty or null, no filtering is applied
 */
public record CustomerFilter(String nameFilter) {

    public boolean matches(Customer customer) {
        if (nameFilter == null || nameFilter.isBlank()) {
            return true;
        }
        String lowerFilter = nameFilter.toLowerCase();
        return customer.firstName().toLowerCase().contains(lowerFilter)
                || customer.lastName().toLowerCase().contains(lowerFilter);
    }
}
